import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  status: ProjectStatus;
}

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Атлас платежей', quotaUsed: 42, status: 'active' },
  { id: 'p2', name: 'Контекст-лаборатория', quotaUsed: 88, status: 'warning' },
  { id: 'p3', name: 'Импорт данных клиентов', quotaUsed: 100, status: 'over' },
  { id: 'p4', name: 'Мобильное приложение', quotaUsed: 15, status: 'active' },
  { id: 'p5', name: 'Внутренний портал', quotaUsed: 67, status: 'warning' },
  { id: 'p6', name: 'Аналитика продаж', quotaUsed: 30, status: 'active' },
  { id: 'p7', name: 'Сервис уведомлений', quotaUsed: 95, status: 'over' },
  { id: 'p8', name: 'Каталог поставщиков', quotaUsed: 55, status: 'active' },
  { id: 'p9', name: 'Биллинг', quotaUsed: 78, status: 'warning' },
  { id: 'p10', name: 'Архив документов', quotaUsed: 12, status: 'active' },
  { id: 'p11', name: 'Логи запросов', quotaUsed: 101, status: 'over' },
  { id: 'p12', name: 'Планировщик задач', quotaUsed: 50, status: 'active' },
];

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'В норме',
  warning: 'Близко к лимиту',
  over: 'Превышена',
};

const STATUS_TONE: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  active: 'success',
  warning: 'warning',
  over: 'danger',
};

const STATUS_FILTERS: ProjectStatus[] = ['active', 'warning', 'over'];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(STATUS_FILTERS);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(STATUS_FILTERS);
    setPage(1);
  };

  const filtered = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        maxWidth: '640px',
      }}
    >
      <div>
        <div
          style={{
            fontFamily: 'var(--jx-font-sans)',
            fontSize: '13px',
            color: 'var(--jx-text-2)',
            marginBottom: '8px',
          }}
        >
          Статус проекта
        </div>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {STATUS_FILTERS.map((status) => (
            <JxChip
              key={status}
              active={activeStatuses.includes(status)}
              removable={activeStatuses.includes(status)}
              onRemove={() => toggleStatus(status)}
              onClick={() => {
                if (!activeStatuses.includes(status)) {
                  toggleStatus(status);
                }
              }}
            >
              {STATUS_LABEL[status]}
            </JxChip>
          ))}
        </div>
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          message="Попробуйте снять часть фильтров, чтобы увидеть больше проектов."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px',
                  borderRadius: 'var(--jx-r)',
                  border: '1px solid var(--jx-border)',
                  background: 'var(--jx-surface-2)',
                }}
              >
                <JxProgressCircle value={Math.min(project.quotaUsed, 100)} showValue />
                <div
                  style={{
                    flex: 1,
                    fontFamily: 'var(--jx-font-sans)',
                    color: 'var(--jx-text)',
                    fontSize: '14px',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {project.name}
                </div>
                <JxBadge tone={STATUS_TONE[project.status]}>{STATUS_LABEL[project.status]}</JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

